  1	/**
  2	 * Credential login, registration and password reset. No third-party provider.
  3	 *
  4	 * Must call (do not reimplement): hashPassword, verifyPassword, consumeRateLimit, emit
  5	 *
  6	 * Note: `TaskflowEventMap` has no authentication event and the type is part of
  7	 * the frozen contract, so the declared `emit` is not reachable from here.
  8	 * Registration still publishes `member.joined` — through
  9	 * `OrganizationService.createOrganization`, which owns that membership row.
 10	 */
 11	import {
 12	  hashPassword,
 13	  hashToken,
 14	  randomToken,
 15	  verifyPassword,
 16	} from "@/lib/hash";
 17	import { consumeRateLimit } from "@/lib/rate-limit";
 18	import { slugify } from "@/lib/slug";
 19	import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
 20	import * as sessionRepo from "@/server/repositories/session-repository";
 21	import * as userRepo from "@/server/repositories/user-repository";
 22	import { toIsoTimestamp } from "@/types/common";
 23	import { createOrganization } from "./organization-service";
 24	import { renderEmail, sendEmail } from "./email-service";
 25	import { createSessionToken } from "./session-service";
 26	import type {
 27	  LoginInput,
 28	  PasswordResetConfirmInput,
 29	  PasswordResetRequestInput,
 30	  RegisterInput,
 31	} from "@/schemas/auth";
 32	import type { OrgId, SessionId } from "@/types/common";
 33	import type { User } from "@/types/member";
 34	import type { Organization } from "@/types/organization";
 35	
 36	/** Buckets guarding the unauthenticated endpoints. */
 37	const LOGIN_BUCKET = "auth:login";
 38	const RESET_BUCKET = "auth:password-reset";
 39	
 40	/**
 41	 * Rate limiting before a session exists has no tenant to charge against, so
 42	 * every unauthenticated attempt is billed to this sentinel bucket.
 43	 */
 44	const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;
 45	
 46	/** How long a password-reset link stays usable. */
 47	const RESET_TTL_MS = 60 * 60 * 1000;
 48	
 49	/**
 50	 * Registration creates the user and their first workspace in one step — a
 51	 * Taskflow account with no organization cannot do anything, so there is no
 52	 * intermediate state where one exists without the other.
 53	 */
 54	export async function register(
 55	  input: RegisterInput,
 56	): Promise<{ user: User; org: Organization }> {
 57	  const existing = await userRepo.findUserByEmail(input.email);
 58	  if (existing) {
 59	    throw new Error("An account with that email already exists");
 60	  }
 61	
 62	  const user = await userRepo.insertUser({
 63	    email: input.email,
 64	    name: input.name,
 65	    passwordHash: await hashPassword(input.password),
 66	  });
 67	
 68	  const org = await createOrganization(user.id, {
 69	    name: `${input.name}'s workspace`,
 70	    slug: slugify(input.name) || "workspace",
 71	    plan: "free",
 72	  });
 73	
 74	  const welcome = await renderEmail("welcome", {
 75	    orgName: org.name,
 76	    recipientName: user.name,
 77	  });
 78	  await sendEmail({ to: user.email, ...welcome });
 79	
 80	  return { user, org };
 81	}
 82	
 83	/**
 84	 * Credential login. The rate limit is charged before the password is checked,
 85	 * so a brute-force run is throttled whether or not it guesses correctly, and
 86	 * both failure modes return the same message.
 87	 */
 88	export async function login(
 89	  input: LoginInput,
 90	): Promise<{ user: User; token: string }> {
 91	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, LOGIN_BUCKET);
 92	  if (!verdict.allowed) {
 93	    throw new Error("Too many sign-in attempts; try again shortly");
 94	  }
 95	
 96	  const user = await userRepo.findUserByEmail(input.email);
 97	  if (!user) throw new Error("Those credentials did not match");
 98	
 99	  const storedHash = await userRepo.findPasswordHash(user.id);
100	  if (!storedHash || !(await verifyPassword(input.password, storedHash))) {
101	    throw new Error("Those credentials did not match");
102	  }
103	
104	  const { token } = await createSessionToken(user.id);
105	
106	  return { user, token };
107	}
108	
109	export async function logout(sessionId: SessionId): Promise<void> {
110	  await sessionRepo.revokeSession(sessionId);
111	}
112	
113	/**
114	 * Always resolves, whether or not the address is known — telling an anonymous
115	 * caller which emails have accounts is an enumeration oracle. Only the token's
116	 * hash is stored; the raw value exists solely inside the email that carries it.
117	 */
118	export async function requestPasswordReset(
119	  input: PasswordResetRequestInput,
120	): Promise<void> {
121	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
122	  if (!verdict.allowed) return;
123	
124	  const user = await userRepo.findUserByEmail(input.email);
125	  if (!user) return;
126	
127	  const token = randomToken(32);
128	  await resetTokenRepo.issueResetToken(
129	    user.id,
130	    hashToken(token),
131	    toIsoTimestamp(new Date(Date.now() + RESET_TTL_MS)),
132	  );
133	
134	  const message = await renderEmail("password-reset", {
135	    recipientName: user.name,
136	    token,
137	    expiresInMinutes: RESET_TTL_MS / 60_000,
138	  });
139	
140	  await sendEmail({ to: user.email, ...message });
141	}
142	
143	/**
144	 * Consumes a reset token and rewrites the password hash. The token is marked
145	 * used before the new hash is written, so a replay of the same link cannot
146	 * overwrite a password the user has since changed again.
147	 */
148	export async function confirmPasswordReset(
149	  input: PasswordResetConfirmInput,
150	): Promise<User> {
151	  const verdict = await consumeRateLimit(ANONYMOUS_ORG, RESET_BUCKET);
152	  if (!verdict.allowed) {
153	    throw new Error("Too many reset attempts; try again shortly");
154	  }
155	
156	  const stored = await resetTokenRepo.findLiveResetToken(
157	    hashToken(input.token),
158	  );
159	  if (!stored) throw new Error("That reset link is no longer valid");
160	
161	  await resetTokenRepo.consumeResetToken(stored.id);
162	  await userRepo.updatePasswordHash(
163	    stored.userId,
164	    await hashPassword(input.password),
165	  );
166	
167	  const user = await userRepo.findUserById(stored.userId);
168	  if (!user) throw new Error("That reset link is no longer valid");
169	
170	  return user;
171	}

